local class = Class("UIDeckGroundTile")

function class:ctor(go)
    --@type CS.UnityEngine.GameObject
    self.gameObject = go
    self.abName = "OutPut/UI/UIDeck/UITile"
    self.prefabName = "UITile"

    self.bgImage = self.gameObject:GetComponent("Image")
    self.eventTrigger = self.gameObject:GetComponent("EventTrigger")
    self.productIcon = ComponentUtilGet.Image(self.gameObject.transform, "img_product")

    self:AddEventTrigger(CS.UnityEngine.EventSystems.EventTriggerType.PointerEnter, function(eventData)
        if self.onPointerEnter then
            self.onPointerEnter(self)
        end
    end)
    self:AddEventTrigger(CS.UnityEngine.EventSystems.EventTriggerType.PointerExit, function(eventData)
        if self.onPointerExit then
            self.onPointerExit(self)
        end
    end)
    self:AddEventTrigger(CS.UnityEngine.EventSystems.EventTriggerType.PointerDown, function(eventData)
        if self.onPointerDown then
            self.onPointerDown(self)
        end
    end)
    self:AddEventTrigger(CS.UnityEngine.EventSystems.EventTriggerType.PointerUp, function(eventData)
        if self.onPointerUp then
            self.onPointerUp(self)
        end
    end)

    self:AddEventTrigger(CS.UnityEngine.EventSystems.EventTriggerType.BeginDrag, function(eventData)
        if self.onBeginDrag then
            self.onBeginDrag(self)
        end
    end)

    self:AddEventTrigger(CS.UnityEngine.EventSystems.EventTriggerType.Drag, function(self,eventData)
        if self.onDrag then
            local pointerData = eventData:ConvertToPointerEventData(eventData)
            self.onDrag(Vector3(pointerData.position.x, pointerData.position.y, 0))
        end
    end)
    GlobalEvent.AddListener(EventID.OnTileDataChange, function(x,y)
        self:OnTileDataChange(x,y)
    end)
end

function class:SetData(tileData)
    self.x = tileData.x
    self.y = tileData.y
    self.tileSize = tileData.tileSize
    self.productData = GameDataManager.GetDeckTileData(self.x, self.y)
