    self.onDrag = tileData.onDrag
    self.onPointerEnter = tileData.onPointerEnter
    self.onPointerExit = tileData.onPointerExit
    self.onPointerDown = tileData.onPointerDown
    self.onPointerUp = tileData.onPointerUp
    self.onBeginDrag = tileData.onBeginDrag

    self:UpdateContent()
    
    print(self.gameObject.name, self.productData.productId, self.productData.productState)
end

function class:UpdateContent()
    self.gameObject.transform.localPosition = self.startPosition + Vector3(self.x * (self.tileSize + 3), self.y * (self.tileSize + 3), 0)
end

function class:AddEventTrigger(eventId, callback)
    local entry = CS.UnityEngine.EventSystems.EventTrigger.Entry()
    entry.eventID = eventId
    entry.callback = CS.UnityEngine.EventSystems.EventTrigger.TriggerEvent()
    entry.callback:AddListener(function(eventData)
        callback(self, eventData)
    end)
    self.eventTrigger.triggers:Add(entry)
end

